/**
 * NFL Data Source Catalog — rights-classified index of every NFL data source
 * the owner has surfaced as a candidate (2026-06-12, 180 URLs).
 *
 * This is the candidate index. It complements SOURCE_RIGHTS_REGISTRY (the
 * canonical, full-schema record for sources we actually extract from). Every
 * URL here is accounted for with an honest rights status so nothing gets
 * ingested without clearance. Per CLAUDE.md legal posture:
 *
 *   - Only OPEN-LICENSED data, DOCUMENTED PUBLIC APIs, or sources that
 *     EXPLICITLY publish public fact downloads receive an "approved_*" status.
 *   - Everything proprietary defaults to permission_required (conservative),
 *     even when the underlying numbers are facts — terms review or written
 *     consent comes first.
 *   - Commercial providers with a known licensable feed/API are vendor_candidate.
 *
 * No status here authorizes evasion (no CAPTCHA/login/paywall bypass, no proxy
 * rotation). Approved-status sources still flow through checkClearance() and
 * carry a RightsSnapshot at extraction time.
 */

import type { SourceRightsStatus, SourceType } from "./source-rights-registry";

export type NflSourceCatalogEntry = {
  readonly id: string;
  readonly name: string;
  readonly url: string;
  readonly status: SourceRightsStatus;
  readonly source_type: SourceType;
  /** True when an adapter already ingests this source today. */
  readonly integrated: boolean;
  /** Canonical registry source_id this maps to, when one exists. */
  readonly registry_id: string | null;
  readonly rationale: string;
  /** Concrete legitimate route to actually USE this source's data ("figure out how to say YES"). */
  readonly path_to_yes: string;
};

const A_OPEN: SourceRightsStatus = "approved_open_license";
const A_PUB: SourceRightsStatus = "approved_public_logged_off";
const A_API: SourceRightsStatus = "approved_api";
const PERM: SourceRightsStatus = "permission_required";
const VENDOR: SourceRightsStatus = "vendor_candidate";

