/** Sources cleared for automated extraction today (still gated by checkClearance). */
export const AUTOMATABLE_STATUSES: readonly SourceRightsStatus[] = [
  "approved_open_license",
  "approved_public_logged_off",
  "approved_api",
  "approved_written_permission",
];

export function isAutomatable(entry: NflSourceCatalogEntry): boolean {
  return AUTOMATABLE_STATUSES.includes(entry.status);
}

export function catalogByStatus(
  status: SourceRightsStatus,
): readonly NflSourceCatalogEntry[] {
  return NFL_SOURCE_CATALOG.filter((e) => e.status === status);
}
